import * as React from "react";
import {type PiCardProps} from "@pihanga2/core";
import {Avatar, AvatarFallback, AvatarImage} from "@/components/ui/avatar";
import {cn} from "@/lib/utils";
import type {AvatarCardProps, AvatarSize} from "./avatar.types";

const SIZE_CLASS: Record<AvatarSize, string> = {
  sm: "size-6 text-xs",
  md: "size-8 text-xs",
  lg: "size-12 text-sm",
  xl: "size-16 text-base",
};

/**
 * `shad/avatar` card component.
 *
 * Renders a shadcn `<Avatar>` with an optional image and a text fallback.
 * The avatar degrades gracefully: if `src` is absent or the image fails to
 * load, the `fallback` initials are shown inside a muted circle.
 */
export const AvatarComponent = (
  props: PiCardProps<AvatarCardProps>,
): React.ReactNode => {
  const {src, alt = "", fallback, size = "md", className, cardName} = props;

  return (
    <Avatar className={cn(SIZE_CLASS[size], className)} data-pihanga={cardName}>
      {src && <AvatarImage src={src} alt={alt} />}
      <AvatarFallback>
        {fallback ?? alt.slice(0, 2).toUpperCase()}
      </AvatarFallback>
    </Avatar>
  );
};

import {createCardDeclaration} from "@pihanga2/core";

export const AVATAR_CARD = "shad/avatar";

/**
 * Avatar size tokens — map to Tailwind `size-*` utilities.
 *
 * | Value  | Tailwind   | px  |
 * |--------|-----------|-----|
 * | `"sm"` | `size-6`  | 24  |
 * | `"md"` | `size-8`  | 32  |
 * | `"lg"` | `size-12` | 48  |
 * | `"xl"` | `size-16` | 64  |
 */
export type AvatarSize = "sm" | "md" | "lg" | "xl";

export type AvatarCardProps = {
  /**
   * URL of the avatar image.
   * When omitted or the image fails to load, `fallback` is shown instead.
   */
  src?: string;

  /** Accessible alt text for the image. */
  alt?: string;

  /**
   * Text rendered inside the fallback circle when no image is available.
   * Typically one or two initials, e.g. `"JD"`.
   */
  fallback?: string;

  /**
   * Avatar diameter.
   * @default "md"
   */
  size?: AvatarSize;

  /** Additional Tailwind classes applied to the root `<span>` element. */
  className?: string;
};

/**
 * Factory function for declaring a `shad/avatar` card instance.
 *
 * ```ts
 * import {ShadAvatar} from "@/cards/avatar";
 *
 * registerCard("myApp/userAvatar", ShadAvatar({
 *   src: memo((s: AppState) => s.user.avatarUrl),
 *   fallback: memo((s: AppState) => s.user.initials),
 * }));
 * ```
 */
export const ShadAvatar = createCardDeclaration<AvatarCardProps>(AVATAR_CARD);

import {registerCardComponent} from "@pihanga2/core";

import {AvatarComponent} from "./avatar.component";
import {AVATAR_CARD} from "./avatar.types";

export * from "./avatar.types";

registerCardComponent({
  name: AVATAR_CARD,
  component: AvatarComponent,
});
